def prefixSuffixString(s1, s2):
    count = 0
    set_s1 = set()
    for word in s1:
        for i in range(1, len(word) + 1):
            set_s1.add(word[:i])  # Add all prefixes
            set_s1.add(word[-i:])  # Add all suffixes
    for word in s2:
        if word in set_s1:
            count += 1
    return count
